1	//! A pure-`std` reimplementation of the `sortedcontainers` C++ header.
2	//!
3	//! The layout follows the C++ library of the same name (itself a port of Python's
4	//! `sortedcontainers`): entries are held in a two-level list of buckets rather than in a
5	//! search tree, so ordered lookups are `O(log n)` while insertion and removal shift
6	//! elements within a single bucket instead of across the whole collection.
7	//!
8	//! * [`buckets`] — the storage engine and its positions.
9	//! * [`cursor`] — [`Cursor`], the stand-in for a C++ iterator.
10	//! * [`sorted_map`] — [`SortedMap`], the public container.
11	
12	// This module is a library: it deliberately offers the whole container API, and re-exports
13	// all of it, even though the program in `test18.rs` exercises only part of it.
14	#![allow(dead_code, unused_imports)]
15	
16	pub mod buckets;
17	pub mod cursor;
18	pub mod sorted_map;
19	
20	pub use self::cursor::Cursor;
21	pub use self::sorted_map::SortedMap;
22	
23	/// Copies every entry of `source` into `target`, overwriting keys that already exist.
24	///
25	/// Mirrors the free function `sortedcontainers::update(target, source)`, whose
26	/// last-write-wins behaviour the original program depends on.
27	pub fn update<K, V>(target: &mut SortedMap<K, V>, source: &SortedMap<K, V>)
28	where
29	    K: Ord + Clone,
30	    V: Clone,
31	{
32	    for (key, value) in source.iter() {
33	        target.insert(key.clone(), value.clone());
34	    }
35	}
36	
37	#[cfg(test)]
38	mod tests {
39	    use super::*;
40	
41	    #[test]
42	    fn update_merges_and_overwrites() {
43	        let mut target: SortedMap<(i32, i32), String> = SortedMap::with_load_factor(2);
44	        for key in 0..6 {
45	            target.insert((key, key * 2), format!("value_{}", key));
46	        }
47	        let mut source: SortedMap<(i32, i32), String> = SortedMap::with_load_factor(2);
48	        for key in 4..9 {
49	            source.insert((key, key * 2), format!("other_{}", key));
50	        }
51	
52	        update(&mut target, &source);
53	
54	        assert_eq!(target.len(), 9);
55	        // Keys only in `target` keep their value; overlapping keys take `source`'s.
56	        assert_eq!(target.get(&(3, 6)).map(String::as_str), Some("value_3"));
57	        assert_eq!(target.get(&(4, 8)).map(String::as_str), Some("other_4"));
58	        assert_eq!(target.get(&(8, 16)).map(String::as_str), Some("other_8"));
59	        assert_eq!(source.len(), 5, "the source must be left untouched");
60	    }
61	
62	    #[test]
63	    fn update_from_an_empty_source_is_a_no_op() {
64	        let mut target: SortedMap<i32, i32> = SortedMap::new();
65	        target.insert(1, 1);
66	        update(&mut target, &SortedMap::new());
67	        assert_eq!(target.len(), 1);
68	    }
69	}
