#[path = "/output/sortedcontainers/mod.rs"]
mod sortedcontainers;

use sortedcontainers::{SortedMap, update};

fn model_lower(keys: &[(i32,i32)], k: &(i32,i32)) -> Option<usize> { keys.iter().position(|x| x >= k) }
fn model_upper(keys: &[(i32,i32)], k: &(i32,i32)) -> Option<usize> { keys.iter().position(|x| x > k) }

fn main() {
    // ---- 1. value() is None on exactly the same condition as cursor == end() ----
    for load in [1usize,2,3,7,512] {
        let mut m: SortedMap<(i32,i32), String> = SortedMap::with_load_factor(load);
        let mut keys: Vec<(i32,i32)> = Vec::new();
        let mut st = 0x12345678u64;
        let mut next = move || { st ^= st<<13; st ^= st>>7; st ^= st<<17; st };
        for step in 0..3000u64 {
            let a = (next() % 40) as i32; let b = (next() % 3) as i32;
            let k = (a,b);
            if next()%3 == 0 {
                m.remove(&k);
                keys.retain(|x| *x != k);
            } else {
                m.insert(k, format!("v{}", step));
                if !keys.contains(&k) { keys.push(k); keys.sort(); }
            }
            assert_eq!(m.len(), keys.len(), "len load={}", load);
        }
        assert_eq!(m.keys(), keys, "keys load={}", load);
        // keys()/values() alignment
        let ks = m.keys(); let vs = m.values();
        assert_eq!(ks.len(), vs.len());
        for (i,k) in ks.iter().enumerate() {
            assert_eq!(&vs[i], m.get(k).unwrap(), "alignment");
        }
        for a in -2..42 { for b in -1..4 {
            let k = (a,b);
            let c = m.find(&k);
            let is_end = c == m.end();
            assert_eq!(is_end, c.value().is_none(), "find/value disagree {:?}", k);
            assert_eq!(is_end, c.is_end(), "is_end disagrees with ==end() {:?}", k);
            assert_eq!(!is_end, keys.contains(&k), "find presence {:?} load={}", k, load);
            if !is_end { assert_eq!(c.key(), Some(&k)); }

            let lb = m.lower_bound(&k);
            assert_eq!(lb.key(), model_lower(&keys,&k).map(|i| &keys[i]), "lb {:?}", k);
            assert_eq!(lb == m.end(), model_lower(&keys,&k).is_none());
            let ub = m.upper_bound(&k);
            assert_eq!(ub.key(), model_upper(&keys,&k).map(|i| &keys[i]), "ub {:?}", k);
            assert_eq!(ub == m.end(), model_upper(&keys,&k).is_none());

            // equal_range loop exactly like the C++ for-loop
            let (first,last) = m.equal_range(&k);
            let mut cur = first; let mut count = 0u32;
            let mut guard = 0u32;
            while cur != last {
                count += 1; cur.advance();
                guard += 1;
                assert!(guard < 100000, "equal_range loop did not terminate for {:?}", k);
            }
            assert_eq!(count as usize, if keys.contains(&k) {1} else {0}, "count {:?}", k);
        }}
        // full walk via cursor reaches every entry once, in keys() order
        let mut cur = m.lower_bound(&(i32::MIN, i32::MIN));
        let mut walked = Vec::new();
        while cur != m.end() { walked.push(*cur.key().unwrap()); cur.advance(); }
        assert_eq!(walked, keys, "walk load={}", load);
        // advancing the end cursor is saturating
        let mut e = m.end(); e.advance(); assert!(e == m.end());
    }

    // ---- 2. empty map: end() self-equality, equal_range empty, no infinite loop ----
    let em: SortedMap<(i32,i32), String> = SortedMap::new();
    assert!(em.end() == em.end());
    assert!(em.find(&(0,0)) == em.end());
    let (f,l) = em.equal_range(&(0,0));
    assert!(f == l, "empty map equal_range must be degenerate");
    let mut c = f; let mut n = 0; while c != l { n+=1; c.advance(); assert!(n < 10); }
    assert_eq!(n, 0);

    // ---- 3. cursors into two DIFFERENT maps never compare equal, even when both empty ----
    let a: SortedMap<(i32,i32), String> = SortedMap::new();
    let b: SortedMap<(i32,i32), String> = SortedMap::new();
    assert!(a.end() != b.end(), "distinct empty maps compared equal!");
    // ZST value type
    let za: SortedMap<(), ()> = SortedMap::new();
    let zb: SortedMap<(), ()> = SortedMap::new();
    assert!(za.end() != zb.end(), "ZST-typed distinct maps compared equal!");
    let mut zc: SortedMap<(), ()> = SortedMap::new();
    zc.insert((), ());
    assert_eq!(zc.len(), 1);
    assert!(zc.find(&()) != zc.end());
    assert_eq!(zc.find(&()).value(), Some(&()));

    // ---- 4. same map, cursors obtained through separate borrows compare equal ----
    let mut m: SortedMap<(i32,i32), String> = SortedMap::with_load_factor(2);
    for i in 0..9 { m.insert((i,i*2), format!("v{}", i)); }
    assert!(m.find(&(4,8)) == m.lower_bound(&(4,8)));
    assert!(m.upper_bound(&(3,6)) == m.find(&(4,8)));
    // through a Box / reference indirection
    let boxed = Box::new(m);
    assert!(boxed.find(&(4,8)) == boxed.lower_bound(&(4,8)));
    let r: &SortedMap<(i32,i32), String> = &*boxed;
    assert!(r.end() == boxed.end());

    // ---- 5. update() overwrite direction ----
    let mut t: SortedMap<i32, &'static str> = SortedMap::new();
    t.insert(1, "target"); t.insert(2, "target");
    let mut s: SortedMap<i32, &'static str> = SortedMap::new();
    s.insert(2, "source"); s.insert(3, "source");
    update(&mut t, &s);
    assert_eq!(t.len(), 3);
    assert_eq!(t.get(&1), Some(&"target"));
    assert_eq!(t.get(&2), Some(&"source"), "update must be last-write-wins from source");
    assert_eq!(s.len(), 2);

    // ---- 6. get_or must not insert; entry_or_default must ----
    let mut g: SortedMap<i32, String> = SortedMap::new();
    let fb = String::from("default");
    assert_eq!(g.get_or(&7, &fb), "default");
    assert_eq!(g.len(), 0, "get_or inserted!");
    assert_eq!(g.entry_or_default(7), "");
    assert_eq!(g.len(), 1, "entry_or_default did not insert");

    // ---- 7. tuple ordering matches std::tuple lexicographic ----
    let mut o: SortedMap<(i32,i32), i32> = SortedMap::with_load_factor(1);
    for k in [(1,-5),(1,7),(-3,9),(0,0),(-3,-9),(i32::MIN,i32::MAX),(i32::MAX,i32::MIN)] { o.insert(k, 0); }
    assert_eq!(o.keys(), vec![(i32::MIN,i32::MAX),(-3,-9),(-3,9),(0,0),(1,-5),(1,7),(i32::MAX,i32::MIN)]);

    println!("ALL CURSOR PROBES PASSED");
}
